private List<DateFormat> loadDateFormats() {
    List<DateFormat> dateFormats = new ArrayList<>();
    // yyyy-mm-ddThh...
    // UTC/Zulu
    dateFormats.add(createDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'", UTC));
    // With timezone
    dateFormats.add(createDateFormat("yyyy-MM-dd'T'HH:mm:ssZ", null));
    // Without timezone
    dateFormats.add(createDateFormat("yyyy-MM-dd'T'HH:mm:ss", null));
    // yyyy-mm-dd hh...
    // UTC/Zulu
    dateFormats.add(createDateFormat("yyyy-MM-dd' 'HH:mm:ss'Z'", UTC));
    // With timezone
    dateFormats.add(createDateFormat("yyyy-MM-dd' 'HH:mm:ssZ", null));
    // Without timezone
    dateFormats.add(createDateFormat("yyyy-MM-dd' 'HH:mm:ss", null));
    // Date without time, set to Midday UTC
    // Normal date format
    dateFormats.add(createDateFormat("yyyy-MM-dd", MIDDAY));
    dateFormats.add(createDateFormat("yyyy:MM:dd", // Image (IPTC/EXIF) format
    MIDDAY));
    return dateFormats;
}
